#[wasm_bindgen]
pub fn fv_version() -> String {
    "FV-Lang 0.1.0 (WASM)".to_string()
}

// 내부 평가 함수
fn run_fv_code(code: &str) -> EvalResult {
    // Lexer
    let lexer = fv_lang::Lexer::new(code);
    let tokens = match lexer.tokenize() {
        Ok(t) => t,
        Err(e) => return EvalResult {
            success: false,
            output: String::new(),
            error: Some(format!("Lexer 오류: {}", e)),
            ast_json: None,
        },
    };

    // Parser
    let parser = fv_lang::Parser::new(tokens);
    let ast = match parser.parse() {
        Ok(a) => a,
        Err(e) => return EvalResult {
            success: false,
            output: String::new(),
            error: Some(format!("Parse 오류: {}", e)),
            ast_json: None,
        },
    };

    let ast_str = format!("{:#?}", ast);

    // Compile
    match fv_lang::compile(code) {
        Ok(output) => EvalResult {
            success: true,
            output,
            error: None,
            ast_json: Some(ast_str),
        },
        Err(e) => EvalResult {
            success: false,
            output: String::new(),
            error: Some(format!("컴파일 오류: {}", e)),
            ast_json: Some(ast_str),
        },
    }
}

