mod tests {
    use super::*;

    #[test]
    fn test_type_checker_new() {
        let checker = TypeChecker::new();
        assert_eq!(checker.get_errors().len(), 0);
    }

    #[test]
    fn test_check_integer_literal() {
        let mut checker = TypeChecker::new();
        let expr = Expression::Literal(Literal::Integer(42));
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Integer));
    }

    #[test]
    fn test_check_string_literal() {
        let mut checker = TypeChecker::new();
        let expr = Expression::Literal(Literal::String("hello".to_string()));
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::String));
    }

    #[test]
    fn test_check_boolean_literal() {
        let mut checker = TypeChecker::new();
        let expr = Expression::Literal(Literal::Boolean(true));
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Boolean));
    }

    #[test]
    fn test_check_undefined_variable() {
        let mut checker = TypeChecker::new();
        let expr = Expression::Variable("undefined".to_string());
        let result = checker.check_expression(&expr);
        assert!(result.is_err());
    }

    #[test]
    fn test_check_arithmetic_integers() {
        let mut checker = TypeChecker::new();
        let expr = Expression::BinaryOp {
            op: "Plus".to_string(),
            left: Box::new(Expression::Literal(Literal::Integer(1))),
            right: Box::new(Expression::Literal(Literal::Integer(2))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Integer));
    }

    #[test]
    fn test_check_arithmetic_incompatible() {
        let mut checker = TypeChecker::new();
        let expr = Expression::BinaryOp {
            op: "Plus".to_string(),
            left: Box::new(Expression::Literal(Literal::Integer(1))),
            right: Box::new(Expression::Literal(Literal::String("hello".to_string()))),
        };
        let result = checker.check_expression(&expr);
        assert!(result.is_err());
    }

    #[test]
    fn test_check_comparison() {
        let mut checker = TypeChecker::new();
        let expr = Expression::BinaryOp {
            op: "Eq".to_string(),
            left: Box::new(Expression::Literal(Literal::Integer(1))),
            right: Box::new(Expression::Literal(Literal::Integer(2))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Boolean));
    }

    #[test]
    fn test_check_logical_operation() {
        let mut checker = TypeChecker::new();
        let expr = Expression::BinaryOp {
            op: "And".to_string(),
            left: Box::new(Expression::Literal(Literal::Boolean(true))),
            right: Box::new(Expression::Literal(Literal::Boolean(false))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Boolean));
    }

    #[test]
    fn test_check_unary_not() {
        let mut checker = TypeChecker::new();
        let expr = Expression::UnaryOp {
            op: "Not".to_string(),
            operand: Box::new(Expression::Literal(Literal::Boolean(true))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Boolean));
    }

    #[test]
    fn test_check_unary_minus() {
        let mut checker = TypeChecker::new();
        let expr = Expression::UnaryOp {
            op: "Minus".to_string(),
            operand: Box::new(Expression::Literal(Literal::Integer(42))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Integer));
    }

    #[test]
    fn test_check_if_expression() {
        let mut checker = TypeChecker::new();
        let expr = Expression::IfExpr {
            condition: Box::new(Expression::Literal(Literal::Boolean(true))),
            then_expr: Box::new(Expression::Literal(Literal::Integer(1))),
            else_expr: Some(Box::new(Expression::Literal(Literal::Integer(2)))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Integer));
    }

    #[test]
    fn test_check_if_expression_type_mismatch() {
        let mut checker = TypeChecker::new();
        let expr = Expression::IfExpr {
            condition: Box::new(Expression::Literal(Literal::Boolean(true))),
            then_expr: Box::new(Expression::Literal(Literal::Integer(1))),
            else_expr: Some(Box::new(Expression::Literal(Literal::String("hello".to_string())))),
        };
        let result = checker.check_expression(&expr);
        assert!(result.is_err());
    }

    #[test]
    fn test_check_arithmetic_mixed_numeric() {
        let mut checker = TypeChecker::new();
        let expr = Expression::BinaryOp {
            op: "Plus".to_string(),
            left: Box::new(Expression::Literal(Literal::Integer(1))),
            right: Box::new(Expression::Literal(Literal::Float(2.5))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Float));
    }

    #[test]
    fn test_check_logical_operation_invalid() {
        let mut checker = TypeChecker::new();
