// 타입 검사기
// Phase 3: 타입 검사 및 의미 분석

use crate::ast::*;
use crate::types::Type;
use crate::symbols::SymbolTable;
use std::collections::HashMap;

/// 함수 시그니처
#[derive(Debug, Clone)]
pub struct FunctionSignature {
    pub name: String,
    pub params: Vec<(String, Type)>,
    pub return_type: Type,
}

/// 타입 검사 에러
#[derive(Debug, Clone)]
pub struct TypeError {
    pub message: String,
}

impl TypeError {
    pub fn new(message: String) -> Self {
        TypeError { message }
    }
}

impl std::fmt::Display for TypeError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "타입 에러: {}", self.message)
    }
}

/// 타입 검사를 수행하는 구조체
pub struct TypeChecker {
    symbol_table: SymbolTable,
    errors: Vec<TypeError>,
    function_signatures: HashMap<String, FunctionSignature>,
}

impl TypeChecker {
    /// 새로운 타입 검사기를 생성합니다
    pub fn new() -> Self {
        TypeChecker {
            symbol_table: SymbolTable::new(),
            errors: Vec::new(),
            function_signatures: HashMap::new(),
        }
    }

    /// 프로그램 전체를 타입 검사합니다
    pub fn check(&mut self, program: &Program) -> Result<(), Vec<TypeError>> {
        for definition in &program.definitions {
            if let Err(e) = self.check_definition(definition) {
                self.errors.push(e);
            }
        }

        if self.errors.is_empty() {
            Ok(())
        } else {
            Err(self.errors.clone())
        }
    }

    /// 정의를 타입 검사합니다
    fn check_definition(&mut self, def: &Definition) -> Result<(), TypeError> {
        match def {
            Definition::Function { name, params, body } => {
                // 함수 시그니처 저장 (매개변수는 현재 Unknown 타입)
                let param_types: Vec<(String, Type)> = params
                    .iter()
                    .map(|p| (p.clone(), Type::Unknown))
                    .collect();

                let signature = FunctionSignature {
                    name: name.clone(),
                    params: param_types,
                    return_type: Type::Unknown,
                };

                self.function_signatures.insert(name.clone(), signature);

                self.symbol_table.enter_scope();

                // 매개변수를 심볼 테이블에 추가
                // 현재는 타입 정보가 없으므로 Unknown으로 설정
                for param in params {
                    self.symbol_table.define(
                        param.clone(),
                        Type::Unknown,
                        false,
                    ).map_err(|e| TypeError::new(e))?;
                }

                // 함수 본문 검사
                for stmt in body {
                    self.check_statement(stmt)?;
                }

                self.symbol_table.exit_scope();
                Ok(())
            }
            Definition::TypeDef { name: _ } => {
                // 타입 정의는 현재 검사할 것이 없음
                Ok(())
            }
        }
    }

    /// 문장을 타입 검사합니다
    fn check_statement(&mut self, stmt: &Statement) -> Result<Type, TypeError> {
        match stmt {
            Statement::LetBinding { name, value } => {
                let value_type = self.check_expression(value)?;
                self.symbol_table.define(name.clone(), value_type.clone(), true)
                    .map_err(|e| TypeError::new(e))?;
                Ok(value_type)
            }
            Statement::Return(expr) => {
                self.check_expression(expr)
            }
            Statement::If {
                condition,
                then_branch,
                else_branch,
            } => {
                let cond_type = self.check_expression(condition)?;

                // 조건은 boolean이어야 함
                if cond_type != Type::Boolean && cond_type != Type::Unknown {
                    return Err(TypeError::new(
                        format!("조건은 bool 타입이어야 하지만 {:?}을(를) 받음", cond_type),
                    ));
                }

                // then 브랜치는 새로운 스코프에서 검사
                self.symbol_table.enter_scope();
                for then_stmt in then_branch {
                    self.check_statement(then_stmt)?;
                }
                self.symbol_table.exit_scope();

                // else 브랜치도 새로운 스코프에서 검사
                if let Some(else_stmts) = else_branch {
                    self.symbol_table.enter_scope();
                    for else_stmt in else_stmts {
                        self.check_statement(else_stmt)?;
                    }
                    self.symbol_table.exit_scope();
                }

                Ok(Type::Unknown)
            }
            Statement::Expression(expr) => {
                self.check_expression(expr)
            }
        }
    }

    /// 표현식을 타입 검사합니다
    pub fn check_expression(&mut self, expr: &Expression) -> Result<Type, TypeError> {
        match expr {
            Expression::Literal(lit) => {
                match lit {
                    Literal::Integer(_) => Ok(Type::Integer),
                    Literal::Float(_) => Ok(Type::Float),
                    Literal::String(_) => Ok(Type::String),
                    Literal::Boolean(_) => Ok(Type::Boolean),
                }
            }
            Expression::Variable(name) => {
                match self.symbol_table.get_type(name) {
                    Some(type_) => Ok(type_),
                    None => Err(TypeError::new(format!("정의되지 않은 변수: '{}'", name))),
                }
            }
            Expression::BinaryOp { op, left, right } => {
                let left_type = self.check_expression(left)?;
                let right_type = self.check_expression(right)?;

                self.check_binary_op(op, &left_type, &right_type)
            }
            Expression::UnaryOp { op, operand } => {
                let operand_type = self.check_expression(operand)?;
                self.check_unary_op(op, &operand_type)
            }
            Expression::FunctionCall { name, args } => {
                // 함수 시그니처 확인
                match self.function_signatures.get(name) {
                    Some(sig) => {
                        // 인자 개수 확인
                        if args.len() != sig.params.len() {
                            return Err(TypeError::new(format!(
                                "함수 '{}': 인자 개수 불일치 (기대: {}, 받음: {})",
                                name,
                                sig.params.len(),
                                args.len()
                            )));
                        }

                        // 각 인자의 타입 확인
                        for (i, (arg, (_, param_type))) in
                            args.iter().zip(sig.params.iter()).enumerate()
                        {
                            let arg_type = self.check_expression(arg)?;
                            if !arg_type.is_compatible(param_type) {
                                return Err(TypeError::new(format!(
                                    "함수 '{}' 인자 {}: 타입 불일치 (기대: {}, 받음: {})",
                                    name, i + 1, param_type, arg_type
                                )));
                            }
                        }

                        Ok(sig.return_type.clone())
                    }
                    None => {
                        // 정의되지 않은 함수
                        Err(TypeError::new(format!("정의되지 않은 함수: '{}'", name)))
                    }
                }
            }
            Expression::IfExpr {
                condition,
                then_expr,
                else_expr,
            } => {
                let cond_type = self.check_expression(condition)?;

                if cond_type != Type::Boolean && cond_type != Type::Unknown {
                    return Err(TypeError::new(
                        format!("조건은 bool 타입이어야 함, 받은 타입: {:?}", cond_type),
                    ));
                }

                let then_type = self.check_expression(then_expr)?;

                if let Some(else_expr) = else_expr {
                    let else_type = self.check_expression(else_expr)?;

                    // then과 else의 타입이 호환되어야 함
                    if then_type.is_compatible(&else_type) {
                        Ok(then_type)
                    } else {
                        Err(TypeError::new(format!(
                            "if 표현식의 분기 타입이 맞지 않음: {} vs {}",
                            then_type, else_type
                        )))
                    }
                } else {
                    Ok(then_type)
                }
            }
            Expression::Match { .. } => {
                // 향후 match 표현식 구현
                Ok(Type::Unknown)
            }
            Expression::Array { elements } => {
                if elements.is_empty() {
                    // 빈 배열은 Unknown 타입
                    Ok(Type::Array {
                        element_type: Box::new(Type::Unknown),
                    })
                } else {
                    // 첫 번째 요소의 타입을 기준으로 함
                    let first_type = self.check_expression(&elements[0])?;

                    // 모든 요소가 같은 타입인지 확인
                    for (i, elem) in elements.iter().enumerate().skip(1) {
                        let elem_type = self.check_expression(elem)?;
                        if !elem_type.is_compatible(&first_type) {
                            return Err(TypeError::new(format!(
                                "배열 요소 {}: 타입 불일치 (기대: {}, 받음: {})",
                                i, first_type, elem_type
                            )));
                        }
                    }

                    Ok(Type::Array {
                        element_type: Box::new(first_type),
                    })
                }
            }
            Expression::Index { expr, index } => {
                let expr_type = self.check_expression(expr)?;
                let index_type = self.check_expression(index)?;

                // 인덱스는 정수여야 함
                if index_type != Type::Integer && index_type != Type::Unknown {
                    return Err(TypeError::new(format!(
                        "배열 인덱스는 정수여야 하지만 {}을(를) 받음",
                        index_type
                    )));
                }

                // 배열 타입이어야 함
                match expr_type {
                    Type::Array { element_type } => Ok(*element_type),
                    Type::Unknown => Ok(Type::Unknown),
                    _ => Err(TypeError::new(format!(
                        "배열 인덱싱은 배열 타입에만 가능하지만 {}을(를) 받음",
                        expr_type
                    ))),
                }
            }
            Expression::Tuple { elements } => {
                let mut tuple_types = Vec::new();

                for elem in elements {
                    let elem_type = self.check_expression(elem)?;
                    tuple_types.push(elem_type);
                }

                Ok(Type::Tuple { types: tuple_types })
            }
        }
    }

    /// 이항 연산을 타입 검사합니다
    fn check_binary_op(
        &self,
        op: &str,
        left_type: &Type,
        right_type: &Type,
    ) -> Result<Type, TypeError> {
        match op {
            // 산술 연산자
            "Plus" | "Minus" | "Star" | "Slash" | "Percent" => {
                if left_type.is_numeric() && right_type.is_numeric() {
                    // 결과 타입은 더 넓은 타입
                    match (left_type, right_type) {
                        (Type::Float, _) | (_, Type::Float) => Ok(Type::Float),
                        _ => Ok(left_type.clone()),
                    }
                } else if *left_type == Type::Unknown || *right_type == Type::Unknown {
                    Ok(Type::Unknown)
                } else {
                    Err(TypeError::new(format!(
                        "산술 연산 '{}'은 숫자 타입이어야 하지만 {} 과 {} 을(를) 받음",
                        op, left_type, right_type
                    )))
                }
            }
            // 비교 연산자
            "Eq" | "Ne" | "Lt" | "Le" | "Gt" | "Ge" => {
                if left_type.is_compatible(right_type) {
                    Ok(Type::Boolean)
                } else if *left_type == Type::Unknown || *right_type == Type::Unknown {
                    Ok(Type::Boolean)
                } else {
                    Err(TypeError::new(format!(
                        "비교 연산 '{}'에서 호환되지 않는 타입: {} 과 {}",
                        op, left_type, right_type
                    )))
                }
            }
            // 논리 연산자
            "And" | "Or" => {
                if left_type == Type::Boolean && right_type == Type::Boolean {
                    Ok(Type::Boolean)
                } else if left_type == Type::Unknown || right_type == Type::Unknown {
                    Ok(Type::Boolean)
                } else {
                    Err(TypeError::new(format!(
                        "논리 연산 '{}'은 bool 타입이어야 하지만 {} 과 {} 을(를) 받음",
                        op, left_type, right_type
                    )))
                }
            }
            _ => Err(TypeError::new(format!("알 수 없는 연산자: '{}'", op))),
        }
    }

    /// 단항 연산을 타입 검사합니다
    fn check_unary_op(&self, op: &str, operand_type: &Type) -> Result<Type, TypeError> {
        match op {
            "Not" => {
                if operand_type == Type::Boolean || operand_type == Type::Unknown {
                    Ok(Type::Boolean)
                } else {
                    Err(TypeError::new(format!(
                        "! 연산은 bool 타입이어야 하지만 {} 을(를) 받음",
                        operand_type
                    )))
                }
            }
            "Minus" => {
                if operand_type.is_numeric() || operand_type == Type::Unknown {
                    Ok(operand_type.clone())
                } else {
                    Err(TypeError::new(format!(
                        "- 연산은 숫자 타입이어야 하지만 {} 을(를) 받음",
                        operand_type
                    )))
                }
            }
            _ => Err(TypeError::new(format!("알 수 없는 단항 연산자: '{}'", op))),
        }
    }

    /// 모든 타입 검사 에러를 반환합니다
    pub fn get_errors(&self) -> &[TypeError] {
        &self.errors
    }

    /// 심볼 테이블의 현재 심볼들을 반환합니다
    pub fn current_symbols(&self) -> Vec<(String, Type)> {
        self.symbol_table
            .current_symbols()
            .into_iter()
            .map(|s| (s.name, s.type_))
            .collect()
    }

    /// 함수 시그니처를 조회합니다
    pub fn get_function_signature(&self, name: &str) -> Option<FunctionSignature> {
        self.function_signatures.get(name).cloned()
    }

    /// 모든 함수 시그니처를 반환합니다
    pub fn all_function_signatures(&self) -> Vec<FunctionSignature> {
        self.function_signatures.values().cloned().collect()
    }

    /// 현재 스코프 깊이를 반환합니다
    pub fn current_scope_depth(&self) -> usize {
        self.symbol_table.current_scope_level()
    }

    /// 변수가 현재 스코프에서 접근 가능한지 확인합니다
    pub fn is_variable_accessible(&self, name: &str) -> bool {
        self.symbol_table.lookup(name).is_some()
    }

    /// 현재 스코프의 모든 변수를 반환합니다
    pub fn current_scope_variables(&self) -> Vec<(String, Type)> {
        self.symbol_table
            .current_symbols()
            .into_iter()
            .map(|s| (s.name, s.type_))
            .collect()
    }
}

impl Default for TypeChecker {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_type_checker_new() {
        let checker = TypeChecker::new();
        assert_eq!(checker.get_errors().len(), 0);
    }

    #[test]
    fn test_check_integer_literal() {
        let mut checker = TypeChecker::new();
        let expr = Expression::Literal(Literal::Integer(42));
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Integer));
    }

    #[test]
    fn test_check_string_literal() {
        let mut checker = TypeChecker::new();
        let expr = Expression::Literal(Literal::String("hello".to_string()));
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::String));
    }

    #[test]
    fn test_check_boolean_literal() {
        let mut checker = TypeChecker::new();
        let expr = Expression::Literal(Literal::Boolean(true));
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Boolean));
    }

    #[test]
    fn test_check_undefined_variable() {
        let mut checker = TypeChecker::new();
        let expr = Expression::Variable("undefined".to_string());
        let result = checker.check_expression(&expr);
        assert!(result.is_err());
    }

    #[test]
    fn test_check_arithmetic_integers() {
        let mut checker = TypeChecker::new();
        let expr = Expression::BinaryOp {
            op: "Plus".to_string(),
            left: Box::new(Expression::Literal(Literal::Integer(1))),
            right: Box::new(Expression::Literal(Literal::Integer(2))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Integer));
    }

    #[test]
    fn test_check_arithmetic_incompatible() {
        let mut checker = TypeChecker::new();
        let expr = Expression::BinaryOp {
            op: "Plus".to_string(),
            left: Box::new(Expression::Literal(Literal::Integer(1))),
            right: Box::new(Expression::Literal(Literal::String("hello".to_string()))),
        };
        let result = checker.check_expression(&expr);
        assert!(result.is_err());
    }

    #[test]
    fn test_check_comparison() {
        let mut checker = TypeChecker::new();
        let expr = Expression::BinaryOp {
            op: "Eq".to_string(),
            left: Box::new(Expression::Literal(Literal::Integer(1))),
            right: Box::new(Expression::Literal(Literal::Integer(2))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Boolean));
    }

    #[test]
    fn test_check_logical_operation() {
        let mut checker = TypeChecker::new();
        let expr = Expression::BinaryOp {
            op: "And".to_string(),
            left: Box::new(Expression::Literal(Literal::Boolean(true))),
            right: Box::new(Expression::Literal(Literal::Boolean(false))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Boolean));
    }

    #[test]
    fn test_check_unary_not() {
        let mut checker = TypeChecker::new();
        let expr = Expression::UnaryOp {
            op: "Not".to_string(),
            operand: Box::new(Expression::Literal(Literal::Boolean(true))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Boolean));
    }

    #[test]
    fn test_check_unary_minus() {
        let mut checker = TypeChecker::new();
        let expr = Expression::UnaryOp {
            op: "Minus".to_string(),
            operand: Box::new(Expression::Literal(Literal::Integer(42))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Integer));
    }

    #[test]
    fn test_check_if_expression() {
        let mut checker = TypeChecker::new();
        let expr = Expression::IfExpr {
            condition: Box::new(Expression::Literal(Literal::Boolean(true))),
            then_expr: Box::new(Expression::Literal(Literal::Integer(1))),
            else_expr: Some(Box::new(Expression::Literal(Literal::Integer(2)))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Integer));
    }

    #[test]
    fn test_check_if_expression_type_mismatch() {
        let mut checker = TypeChecker::new();
        let expr = Expression::IfExpr {
            condition: Box::new(Expression::Literal(Literal::Boolean(true))),
            then_expr: Box::new(Expression::Literal(Literal::Integer(1))),
            else_expr: Some(Box::new(Expression::Literal(Literal::String("hello".to_string())))),
        };
        let result = checker.check_expression(&expr);
        assert!(result.is_err());
    }

    #[test]
    fn test_check_arithmetic_mixed_numeric() {
        let mut checker = TypeChecker::new();
        let expr = Expression::BinaryOp {
            op: "Plus".to_string(),
            left: Box::new(Expression::Literal(Literal::Integer(1))),
            right: Box::new(Expression::Literal(Literal::Float(2.5))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Float));
    }

    #[test]
    fn test_check_logical_operation_invalid() {
        let mut checker = TypeChecker::new();
        let expr = Expression::BinaryOp {
            op: "And".to_string(),
            left: Box::new(Expression::Literal(Literal::Integer(1))),
            right: Box::new(Expression::Literal(Literal::Boolean(true))),
        };
        let result = checker.check_expression(&expr);
        assert!(result.is_err());
    }
}

// 배열 메서드 (Array Methods)
// Phase 6 Stage 2

use crate::value::Value;

/// 배열의 길이를 반환합니다
pub fn length(arr: &[Value]) -> i64 {
    arr.len() as i64
}

/// 배열을 역순으로 정렬합니다
pub fn reverse(arr: &[Value]) -> Vec<Value> {
    let mut reversed = arr.to_vec();
    reversed.reverse();
    reversed
}

/// 배열을 정렬합니다 (숫자 기준)
pub fn sort(arr: &[Value]) -> Result<Vec<Value>, String> {
    let mut sorted = arr.to_vec();
    sorted.sort_by(|a, b| {
        match (a, b) {
            (Value::Integer(x), Value::Integer(y)) => x.cmp(y),
            (Value::Float(x), Value::Float(y)) => {
                x.partial_cmp(y).unwrap_or(std::cmp::Ordering::Equal)
            }
            (Value::Integer(x), Value::Float(y)) => {
                let x_f = *x as f64;
                x_f.partial_cmp(y).unwrap_or(std::cmp::Ordering::Equal)
            }
            (Value::Float(x), Value::Integer(y)) => {
                let y_f = *y as f64;
                x.partial_cmp(&y_f).unwrap_or(std::cmp::Ordering::Equal)
            }
            _ => std::cmp::Ordering::Equal,
        }
    });
    Ok(sorted)
}

/// 배열의 특정 요소를 찾습니다
pub fn find(arr: &[Value], target: &Value) -> Option<i64> {
    arr.iter()
        .position(|v| v.equals(target))
        .map(|pos| pos as i64)
}

/// 배열에 요소가 포함되어 있는지 확인합니다
pub fn includes(arr: &[Value], target: &Value) -> bool {
    arr.iter().any(|v| v.equals(target))
}

/// 배열에서 모든 요소를 맵합니다 (함수형 변환)
pub fn map(arr: &[Value], transformer: impl Fn(&Value) -> Value) -> Vec<Value> {
    arr.iter().map(|v| transformer(v)).collect()
}

/// 배열에서 조건을 만족하는 요소를 필터링합니다
pub fn filter(arr: &[Value], predicate: impl Fn(&Value) -> bool) -> Vec<Value> {
    arr.iter().filter(|v| predicate(v)).collect()
}

/// 배열의 모든 요소를 하나의 값으로 축약합니다
pub fn reduce(arr: &[Value], init: Value, reducer: impl Fn(Value, &Value) -> Value) -> Value {
    arr.iter().fold(init, |acc, v| reducer(acc, v))
}

/// 배열에서 특정 요소를 제거합니다
pub fn remove(arr: &[Value], index: i64) -> Result<Vec<Value>, String> {
    if index < 0 || index >= arr.len() as i64 {
        return Err("Index out of bounds".to_string());
    }

    let mut result = arr.to_vec();
    result.remove(index as usize);
    Ok(result)
}

/// 배열의 마지막 요소를 반환합니다
pub fn last(arr: &[Value]) -> Option<Value> {
    arr.last().cloned()
}

/// 배열의 첫 번째 요소를 반환합니다
pub fn first(arr: &[Value]) -> Option<Value> {
    arr.first().cloned()
}

/// 배열을 구간으로 나눕니다
pub fn slice(arr: &[Value], start: i64, end: i64) -> Result<Vec<Value>, String> {
    let len = arr.len() as i64;
    let start = if start < 0 { (len + start) as usize } else { start as usize };
    let end = if end < 0 { (len + end) as usize } else { end as usize };

    if start > end || start > arr.len() {
        return Err("Invalid slice indices".to_string());
    }

    Ok(arr[start..std::cmp::min(end, arr.len())].to_vec())
}

/// 배열의 모든 요소가 조건을 만족하는지 확인합니다
pub fn every(arr: &[Value], predicate: impl Fn(&Value) -> bool) -> bool {
    arr.iter().all(|v| predicate(v))
}

/// 배열의 어떤 요소가 조건을 만족하는지 확인합니다
pub fn some(arr: &[Value], predicate: impl Fn(&Value) -> bool) -> bool {
    arr.iter().any(|v| predicate(v))
}

