/// Compile FV-Lang source code to string output
pub fn compile(source: &str) -> Result<String, CompileError> {
    // Lexer: Source → Tokens
    let lexer = Lexer::new(source);
    let tokens = lexer.tokenize()?;

    // Parser: Tokens → AST
    let parser = Parser::new(tokens).map_err(|e| CompileError::ParserError(e.to_string()))?;
    let ast = parser.parse()?;

    // Type Checker: AST 검증 (오류 시 첫 번째 오류 반환)
    let mut type_checker = TypeChecker::new();
    type_checker.check(&ast)
        .map_err(|errs| CompileError::TypeError(
            errs.into_iter().map(|e| e.to_string()).collect::<Vec<_>>().join(", ")
        ))?;

    // Code Generator: AST → 출력 코드
    let codegen = CodeGenerator::new();
    let code = codegen.generate(&ast)?;

    Ok(code)
}

#[derive(Debug, Clone)]
pub enum CompileError {
    LexerError(String),
    ParserError(String),
    TypeError(String),
    GenerationError(String),
}

