        assert_eq!(checker.get_errors().len(), 0);
    }

    #[test]
    fn test_check_integer_literal() {
        let mut checker = TypeChecker::new();
        let expr = Expression::Literal(Literal::Integer(42));
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Integer));
    }

    #[test]
    fn test_check_string_literal() {
        let mut checker = TypeChecker::new();
        let expr = Expression::Literal(Literal::String("hello".to_string()));
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::String));
    }

    #[test]
    fn test_check_boolean_literal() {
        let mut checker = TypeChecker::new();
        let expr = Expression::Literal(Literal::Boolean(true));
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Boolean));
    }

    #[test]
    fn test_check_undefined_variable() {
        let mut checker = TypeChecker::new();
        let expr = Expression::Variable("undefined".to_string());
        let result = checker.check_expression(&expr);
        assert!(result.is_err());
    }

    #[test]
    fn test_check_arithmetic_integers() {
        let mut checker = TypeChecker::new();
        let expr = Expression::BinaryOp {
            op: "Plus".to_string(),
            left: Box::new(Expression::Literal(Literal::Integer(1))),
            right: Box::new(Expression::Literal(Literal::Integer(2))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Integer));
    }

    #[test]
    fn test_check_arithmetic_incompatible() {
        let mut checker = TypeChecker::new();
        let expr = Expression::BinaryOp {
            op: "Plus".to_string(),
            left: Box::new(Expression::Literal(Literal::Integer(1))),
            right: Box::new(Expression::Literal(Literal::String("hello".to_string()))),
        };
        let result = checker.check_expression(&expr);
        assert!(result.is_err());
    }

    #[test]
    fn test_check_comparison() {
        let mut checker = TypeChecker::new();
        let expr = Expression::BinaryOp {
            op: "Eq".to_string(),
            left: Box::new(Expression::Literal(Literal::Integer(1))),
            right: Box::new(Expression::Literal(Literal::Integer(2))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Boolean));
    }

    #[test]
    fn test_check_logical_operation() {
        let mut checker = TypeChecker::new();
        let expr = Expression::BinaryOp {
            op: "And".to_string(),
            left: Box::new(Expression::Literal(Literal::Boolean(true))),
            right: Box::new(Expression::Literal(Literal::Boolean(false))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Boolean));
    }

    #[test]
    fn test_check_unary_not() {
        let mut checker = TypeChecker::new();
        let expr = Expression::UnaryOp {
            op: "Not".to_string(),
            operand: Box::new(Expression::Literal(Literal::Boolean(true))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Boolean));
    }

    #[test]
    fn test_check_unary_minus() {
        let mut checker = TypeChecker::new();
        let expr = Expression::UnaryOp {
            op: "Minus".to_string(),
            operand: Box::new(Expression::Literal(Literal::Integer(42))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Integer));
    }

    #[test]
    fn test_check_if_expression() {
        let mut checker = TypeChecker::new();
        let expr = Expression::IfExpr {
            condition: Box::new(Expression::Literal(Literal::Boolean(true))),
            then_expr: Box::new(Expression::Literal(Literal::Integer(1))),
            else_expr: Some(Box::new(Expression::Literal(Literal::Integer(2)))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Integer));
    }

    #[test]
    fn test_check_if_expression_type_mismatch() {
        let mut checker = TypeChecker::new();
        let expr = Expression::IfExpr {
            condition: Box::new(Expression::Literal(Literal::Boolean(true))),
            then_expr: Box::new(Expression::Literal(Literal::Integer(1))),
            else_expr: Some(Box::new(Expression::Literal(Literal::String("hello".to_string())))),
        };
        let result = checker.check_expression(&expr);
        assert!(result.is_err());
    }

    #[test]
    fn test_check_arithmetic_mixed_numeric() {
        let mut checker = TypeChecker::new();
        let expr = Expression::BinaryOp {
            op: "Plus".to_string(),
            left: Box::new(Expression::Literal(Literal::Integer(1))),
            right: Box::new(Expression::Literal(Literal::Float(2.5))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Float));
    }

    #[test]
    fn test_check_logical_operation_invalid() {
        let mut checker = TypeChecker::new();
        let expr = Expression::BinaryOp {
            op: "And".to_string(),
            left: Box::new(Expression::Literal(Literal::Integer(1))),
            right: Box::new(Expression::Literal(Literal::Boolean(true))),
        };
        let result = checker.check_expression(&expr);
        assert!(result.is_err());
    }
}

// 컴파일러 통합 (Compiler Integration)
// Phase 5 Stage 3: 완전한 컴파일 파이프라인

use crate::lexer::Lexer;
use crate::parser::Parser;
use crate::type_checker::TypeChecker;
use crate::codegen::CodeGenerator;
use crate::runtime::{Runtime, RuntimeError};
use crate::value::Value;

/// 컴파일 에러
#[derive(Debug, Clone)]
pub enum CompileError {
    LexerError(String),
    ParserError(String),
    TypeError(String),
    CodegenError(String),
    RuntimeError(String),
}

impl std::fmt::Display for CompileError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            CompileError::LexerError(e) => write!(f, "Lexer error: {}", e),
            CompileError::ParserError(e) => write!(f, "Parser error: {}", e),
            CompileError::TypeError(e) => write!(f, "Type error: {}", e),
            CompileError::CodegenError(e) => write!(f, "Code generation error: {}", e),
            CompileError::RuntimeError(e) => write!(f, "Runtime error: {}", e),
        }
    }
}

impl std::error::Error for CompileError {}

impl From<RuntimeError> for CompileError {
    fn from(err: RuntimeError) -> Self {
        CompileError::RuntimeError(err.to_string())
    }
}

/// 완전한 컴파일러
pub struct Compiler {
    runtime: Runtime,
}

impl Compiler {
    pub fn new() -> Self {
        Compiler {
            runtime: Runtime::new(),
        }
    }

    /// 소스 코드 컴파일 및 실행
    pub fn compile_and_run(&mut self, source: &str) -> Result<Value, CompileError> {
        let lexer = Lexer::new(source)
            .map_err(|e| CompileError::LexerError(e.to_string()))?;
        let tokens = lexer.tokenize()
            .map_err(|e| CompileError::LexerError(e.to_string()))?;

        let parser = Parser::new(tokens)
            .map_err(|e| CompileError::ParserError(e.to_string()))?;
        let ast = parser.parse()
            .map_err(|e| CompileError::ParserError(e.to_string()))?;

        let mut type_checker = TypeChecker::new();
        type_checker.check(&ast)
            .map_err(|errs| CompileError::TypeError(
                errs.into_iter().map(|e| e.to_string()).collect::<Vec<_>>().join(", ")
            ))?;

        let mut codegen = CodeGenerator::new();
        let ir = codegen.ast_to_ir(&ast)
            .map_err(|e| CompileError::CodegenError(e.to_string()))?;

        let result = self.runtime.execute(&ir)?;
        Ok(result)
    }

    /// 소스 코드를 IR로 컴파일만 수행 (실행 X)
    pub fn compile(&mut self, source: &str) -> Result<crate::ir::IRProgram, CompileError> {
        let lexer = Lexer::new(source)
            .map_err(|e| CompileError::LexerError(e.to_string()))?;
        let tokens = lexer.tokenize()
            .map_err(|e| CompileError::LexerError(e.to_string()))?;

        let parser = Parser::new(tokens)
            .map_err(|e| CompileError::ParserError(e.to_string()))?;
        let ast = parser.parse()
            .map_err(|e| CompileError::ParserError(e.to_string()))?;

        let mut type_checker = TypeChecker::new();
        type_checker.check(&ast)
            .map_err(|errs| CompileError::TypeError(
                errs.into_iter().map(|e| e.to_string()).collect::<Vec<_>>().join(", ")
            ))?;

        let mut codegen = CodeGenerator::new();
        let ir = codegen.ast_to_ir(&ast)
            .map_err(|e| CompileError::CodegenError(e.to_string()))?;

        Ok(ir)
    }

    /// 상세 파이프라인: 각 단계별 결과 반환
    pub fn compile_verbose(
        &mut self,
        source: &str,
    ) -> Result<CompilationResult, CompileError> {
        let lexer = Lexer::new(source)
            .map_err(|e| CompileError::LexerError(e.to_string()))?;
        let tokens = lexer.tokenize()
            .map_err(|e| CompileError::LexerError(e.to_string()))?;

        let parser = Parser::new(tokens.clone())
            .map_err(|e| CompileError::ParserError(e.to_string()))?;
        let ast = parser.parse()
            .map_err(|e| CompileError::ParserError(e.to_string()))?;

        let mut type_checker = TypeChecker::new();
        type_checker.check(&ast)
            .map_err(|errs| CompileError::TypeError(
                errs.into_iter().map(|e| e.to_string()).collect::<Vec<_>>().join(", ")
            ))?;

        let mut codegen = CodeGenerator::new();
        let ir = codegen.ast_to_ir(&ast)
            .map_err(|e| CompileError::CodegenError(e.to_string()))?;

        Ok(CompilationResult {
            tokens: tokens.len(),
            ast_nodes: ast.definitions.len(),
            ir_nodes: ir.functions.len() + ir.main.len(),
            success: true,
        })
    }

    pub fn runtime(&self) -> &Runtime {
        &self.runtime
    }

    pub fn runtime_mut(&mut self) -> &mut Runtime {
        &mut self.runtime
    }
}

impl Default for Compiler {
    fn default() -> Self {
        Self::new()
    }
}

/// 컴파일 결과 정보
#[derive(Debug, Clone)]
pub struct CompilationResult {
    pub tokens: usize,
    pub ast_nodes: usize,
    pub ir_nodes: usize,
    pub success: bool,
}

impl CompilationResult {
    pub fn summary(&self) -> String {
        if self.success {
            format!(
                "✅ Compilation successful\n  Tokens: {}\n  AST Nodes: {}\n  IR Nodes: {}",
                self.tokens, self.ast_nodes, self.ir_nodes
            )
        } else {
            "❌ Compilation failed".to_string()
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_compiler_create() {
        let _compiler = Compiler::new();
    }

    #[test]
    fn test_compiler_simple_literal() {
        let mut compiler = Compiler::new();
        let result = compiler.compile_and_run("42");
        assert!(result.is_ok() || result.is_err());
    }

    #[test]
    fn test_compile_error_handling() {
        let mut compiler = Compiler::new();
        let result = compiler.compile_and_run("invalid syntax!!!");
        assert!(result.is_err() || result.is_ok());
    }
}

