        assert_eq!(average(&arr), Some(4.0));
    }

    #[test]
    fn test_maximum() {
        let arr = vec![Value::Integer(3), Value::Integer(1), Value::Integer(4), Value::Integer(1)];
        assert_eq!(maximum(&arr), Some(4.0));
    }

    #[test]
    fn test_minimum() {
        let arr = vec![Value::Integer(3), Value::Integer(1), Value::Integer(4), Value::Integer(1)];
        assert_eq!(minimum(&arr), Some(1.0));
    }

    #[test]
    fn test_unique() {
        let arr = vec![
            Value::Integer(1),
            Value::Integer(2),
            Value::Integer(1),
            Value::Integer(3),
        ];
