// 파일 시스템 모듈 (File System)
// FreeLang stdlib - fs

use crate::value::Value;
use std::fs;
use std::io::{Read, Write};

/// 텍스트 파일 읽기
pub fn read_file(path: &str) -> Result<Value, String> {
    fs::read_to_string(path)
        .map(Value::String)
        .map_err(|e| format!("fs::read_file 오류: {}", e))
}

/// 텍스트 파일 쓰기
pub fn write_file(path: &str, content: &str) -> Result<Value, String> {
    fs::write(path, content)
        .map(|_| Value::Boolean(true))
        .map_err(|e| format!("fs::write_file 오류: {}", e))
}

/// 바이너리 파일 읽기 → 바이트 배열
pub fn read_bytes(path: &str) -> Result<Value, String> {
    fs::read(path)
        .map(|bytes| {
            Value::Array(
                bytes.into_iter()
                    .map(|b| Value::Integer(b as i64))
                    .collect()
            )
        })
        .map_err(|e| format!("fs::read_bytes 오류: {}", e))
}

/// 바이트 배열 → 파일 쓰기
pub fn write_bytes(path: &str, bytes: &[Value]) -> Result<Value, String> {
    let raw: Result<Vec<u8>, String> = bytes.iter().map(|v| {
        match v {
            Value::Integer(n) if *n >= 0 && *n <= 255 => Ok(*n as u8),
            _ => Err(format!("바이트 범위 초과: {:?}", v)),
        }
    }).collect();

    fs::write(path, raw?)
        .map(|_| Value::Boolean(true))
        .map_err(|e| format!("fs::write_bytes 오류: {}", e))
}

/// 파일 존재 여부
pub fn file_exists(path: &str) -> Value {
    Value::Boolean(std::path::Path::new(path).exists())
}

/// 파일 삭제
pub fn delete_file(path: &str) -> Result<Value, String> {
    fs::remove_file(path)
        .map(|_| Value::Boolean(true))
        .map_err(|e| format!("fs::delete_file 오류: {}", e))
}

/// 디렉토리 생성
pub fn make_dir(path: &str) -> Result<Value, String> {
    fs::create_dir_all(path)
        .map(|_| Value::Boolean(true))
        .map_err(|e| format!("fs::make_dir 오류: {}", e))
}

/// 디렉토리 내 파일 목록
pub fn list_dir(path: &str) -> Result<Value, String> {
    fs::read_dir(path)
        .map_err(|e| format!("fs::list_dir 오류: {}", e))?
        .map(|entry| {
            entry.map(|e| Value::String(e.path().to_string_lossy().to_string()))
                 .map_err(|e| format!("항목 읽기 오류: {}", e))
        })
        .collect::<Result<Vec<Value>, String>>()
        .map(Value::Array)
}

/// 파일 크기 (바이트)
pub fn file_size(path: &str) -> Result<Value, String> {
    fs::metadata(path)
        .map(|m| Value::Integer(m.len() as i64))
        .map_err(|e| format!("fs::file_size 오류: {}", e))
}

