use crate::value::Value;

/// 바이트 배열을 UTF-8 문자열로 변환
pub fn bytes_to_string(bytes: &[Value]) -> Result<Value, String> {
    let raw: Result<Vec<u8>, String> = bytes.iter().map(|v| {
        match v {
            Value::Integer(n) if *n >= 0 && *n <= 255 => Ok(*n as u8),
            _ => Err(format!("바이트 범위 초과: {:?}", v)),
        }
    }).collect();

    String::from_utf8(raw?)
        .map(Value::String)
        .map_err(|e| format!("UTF-8 변환 오류: {}", e))
}

/// 문자열 → 바이트 배열
pub fn string_to_bytes(s: &str) -> Value {
    Value::Array(
        s.as_bytes().iter()
            .map(|b| Value::Integer(*b as i64))
            .collect()
    )
}

/// i32 → 리틀엔디안 4바이트
pub fn i32_to_le_bytes(n: i64) -> Value {
    let bytes = (n as i32).to_le_bytes();
    Value::Array(bytes.iter().map(|b| Value::Integer(*b as i64)).collect())
}

/// i64 → 리틀엔디안 8바이트
pub fn i64_to_le_bytes(n: i64) -> Value {
    let bytes = n.to_le_bytes();
    Value::Array(bytes.iter().map(|b| Value::Integer(*b as i64)).collect())
}

/// 리틀엔디안 4바이트 → i32
pub fn le_bytes_to_i32(bytes: &[Value]) -> Result<Value, String> {
    if bytes.len() < 4 {
        return Err(format!("4바이트 필요, {}바이트 제공", bytes.len()));
    }
    let raw: Vec<u8> = bytes[..4].iter().map(|v| match v {
        Value::Integer(n) => *n as u8,
        _ => 0,
    }).collect();
    Ok(Value::Integer(i32::from_le_bytes([raw[0], raw[1], raw[2], raw[3]]) as i64))
}

/// 리틀엔디안 8바이트 → i64
pub fn le_bytes_to_i64(bytes: &[Value]) -> Result<Value, String> {
    if bytes.len() < 8 {
        return Err(format!("8바이트 필요, {}바이트 제공", bytes.len()));
    }
    let raw: Vec<u8> = bytes[..8].iter().map(|v| match v {
        Value::Integer(n) => *n as u8,
        _ => 0,
    }).collect();
    Ok(Value::Integer(i64::from_le_bytes(raw.try_into().unwrap())))
}

/// 바이트 배열 슬라이스
pub fn bytes_slice(bytes: &[Value], start: i64, end: i64) -> Value {
    let s = start.max(0) as usize;
    let e = (end as usize).min(bytes.len());
    Value::Array(bytes[s..e].to_vec())
}

/// 두 바이트 배열 연결
pub fn bytes_concat(a: &[Value], b: &[Value]) -> Value {
    let mut result = a.to_vec();
    result.extend_from_slice(b);
    Value::Array(result)
}

/// 16진수 문자열 → 바이트 배열
pub fn hex_to_bytes(hex: &str) -> Result<Value, String> {
    let hex = hex.trim_start_matches("0x");
    if hex.len() % 2 != 0 {
        return Err("16진수 문자열 길이가 짝수여야 합니다".to_string());
    }
    (0..hex.len())
        .step_by(2)
        .map(|i| {
            u8::from_str_radix(&hex[i..i+2], 16)
                .map(|b| Value::Integer(b as i64))
                .map_err(|e| format!("16진수 변환 오류: {}", e))
        })
        .collect::<Result<Vec<Value>, String>>()
        .map(Value::Array)
}

/// 바이트 배열 → 16진수 문자열
pub fn bytes_to_hex(bytes: &[Value]) -> Value {
    let hex: String = bytes.iter().map(|v| {
        match v {
            Value::Integer(n) => format!("{:02x}", n),
            _ => "??".to_string(),
        }
    }).collect();
    Value::String(hex)
}

/// XOR 연산 (두 바이트 배열)
pub fn bytes_xor(a: &[Value], b: &[Value]) -> Value {
    let len = a.len().min(b.len());
    let result: Vec<Value> = (0..len).map(|i| {
        match (&a[i], &b[i]) {
            (Value::Integer(x), Value::Integer(y)) => Value::Integer(x ^ y),
            _ => Value::Integer(0),
        }
    }).collect();
    Value::Array(result)
}

