// 시스템 호출 모듈 (System)
// FreeLang stdlib - sys

use crate::value::Value;
use std::process::{Command, Stdio};

/// 셸 명령어 실행 → stdout 반환
pub fn exec(cmd: &str) -> Result<Value, String> {
    let output = Command::new("sh")
        .arg("-c")
        .arg(cmd)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .output()
        .map_err(|e| format!("sys::exec 오류: {}", e))?;

    let stdout = String::from_utf8_lossy(&output.stdout).to_string();
    let stderr = String::from_utf8_lossy(&output.stderr).to_string();
    let code = output.status.code().unwrap_or(-1) as i64;

    Ok(Value::Array(vec![
        Value::Integer(code),
        Value::String(stdout),
        Value::String(stderr),
    ]))
}

/// 환경변수 읽기
pub fn get_env(key: &str) -> Value {
    match std::env::var(key) {
        Ok(v) => Value::String(v),
        Err(_) => Value::None,
    }
}

/// 환경변수 설정
pub fn set_env(key: &str, val: &str) -> Value {
    std::env::set_var(key, val);
    Value::Boolean(true)
}

/// 프로세스 종료
pub fn exit(code: i64) -> ! {
    std::process::exit(code as i32)
}

/// 현재 작업 디렉토리
pub fn cwd() -> Value {
    std::env::current_dir()
        .map(|p| Value::String(p.to_string_lossy().to_string()))
        .unwrap_or(Value::String(".".to_string()))
}

/// 디렉토리 변경
pub fn chdir(path: &str) -> Result<Value, String> {
    std::env::set_current_dir(path)
        .map(|_| Value::Boolean(true))
        .map_err(|e| format!("sys::chdir 오류: {}", e))
}

/// 명령어 인자 목록
pub fn args() -> Value {
    Value::Array(
        std::env::args()
            .map(Value::String)
            .collect()
    )
}

