/// 최소 ELF64 실행 파일 헤더 생성 (Linux aarch64)
/// code: x86-64 또는 aarch64 머신 코드 바이트 배열
pub fn create_elf64(code: &[Value], entry_offset: i64) -> Result<Value, String> {
    let machine_code: Result<Vec<u8>, String> = code.iter().map(|v| {
        match v {
            Value::Integer(n) if *n >= 0 && *n <= 255 => Ok(*n as u8),
            _ => Err(format!("코드 바이트 범위 초과: {:?}", v)),
        }
    }).collect();
    let machine_code = machine_code?;

    let code_len = machine_code.len() as u64;
    let load_addr: u64 = 0x400000;
    let code_offset: u64 = 0x78; // ELF 헤더 + 1 프로그램 헤더
    let entry_addr = load_addr + code_offset + entry_offset as u64;
    let file_size = code_offset + code_len;

    let mut elf = Vec::new();

    // ELF 헤더 (64바이트)
    elf.extend_from_slice(b"\x7fELF");     // 매직
    elf.push(2);                            // 64bit
    elf.push(1);                            // 리틀엔디안
    elf.push(1);                            // ELF 버전
    elf.push(0);                            // OS/ABI: System V
    elf.extend_from_slice(&[0u8; 8]);       // 패딩
    elf.extend_from_slice(&2u16.to_le_bytes());  // ET_EXEC
    elf.extend_from_slice(&0xb7u16.to_le_bytes()); // aarch64
    elf.extend_from_slice(&1u32.to_le_bytes());  // ELF 버전
    elf.extend_from_slice(&entry_addr.to_le_bytes()); // 엔트리 포인트
    elf.extend_from_slice(&64u64.to_le_bytes());  // 프로그램 헤더 오프셋
    elf.extend_from_slice(&0u64.to_le_bytes());   // 섹션 헤더 없음
    elf.extend_from_slice(&0u32.to_le_bytes());   // 플래그
    elf.extend_from_slice(&64u16.to_le_bytes());  // ELF 헤더 크기
    elf.extend_from_slice(&56u16.to_le_bytes());  // 프로그램 헤더 크기
    elf.extend_from_slice(&1u16.to_le_bytes());   // 프로그램 헤더 개수
    elf.extend_from_slice(&64u16.to_le_bytes());  // 섹션 헤더 크기
    elf.extend_from_slice(&0u16.to_le_bytes());   // 섹션 헤더 개수
    elf.extend_from_slice(&0u16.to_le_bytes());   // 문자열 섹션 인덱스

    // 프로그램 헤더 (56바이트)
    elf.extend_from_slice(&1u32.to_le_bytes());   // PT_LOAD
    elf.extend_from_slice(&5u32.to_le_bytes());   // PF_R | PF_X
    elf.extend_from_slice(&0u64.to_le_bytes());   // 파일 오프셋
    elf.extend_from_slice(&load_addr.to_le_bytes()); // 가상 주소
    elf.extend_from_slice(&load_addr.to_le_bytes()); // 물리 주소
    elf.extend_from_slice(&file_size.to_le_bytes()); // 파일 크기
    elf.extend_from_slice(&file_size.to_le_bytes()); // 메모리 크기
    elf.extend_from_slice(&0x1000u64.to_le_bytes()); // 정렬

    // 머신 코드
    elf.extend_from_slice(&machine_code);

    Ok(Value::Array(elf.iter().map(|b| Value::Integer(*b as i64)).collect()))
}

/// ELF 파일을 디스크에 저장하고 실행 권한 부여
pub fn write_executable(path: &str, elf_bytes: &[Value]) -> Result<Value, String> {
    let raw: Result<Vec<u8>, String> = elf_bytes.iter().map(|v| {
        match v {
            Value::Integer(n) => Ok(*n as u8),
            _ => Err("바이트 오류".to_string()),
        }
    }).collect();

    fs::write(path, raw?)
        .map_err(|e| format!("쓰기 오류: {}", e))?;

    // 실행 권한 (chmod +x)
    let mut perms = fs::metadata(path)
        .map_err(|e| e.to_string())?
        .permissions();
    perms.set_mode(0o755);
    fs::set_permissions(path, perms)
        .map_err(|e| format!("권한 설정 오류: {}", e))?;

    Ok(Value::Boolean(true))
}

