#[derive(Debug, Clone)]
pub struct Runtime {
    /// 힙 메모리
    heap: Heap,
    /// 호출 스택
    stack: Stack,
    /// 프로그램 카운터
    pc: usize,
    /// 정의된 함수들
    functions: HashMap<String, FunctionDef>,
    /// 반환값 저장소
    return_value: Option<Value>,
}

impl Runtime {
    /// 새 런타임 생성
    pub fn new() -> Self {
        Runtime {
            heap: Heap::new(),
            stack: Stack::new(),
            pc: 0,
            functions: HashMap::new(),
            return_value: None,
        }
    }

    /// 프로그램 실행
    pub fn execute(&mut self, nodes: &[IRNode]) -> Result<Value, RuntimeError> {
