// FV-Lang Compiler & Interpreter
// Command-line interface

use fv_lang::compile;
use fv_lang::compiler::Compiler;
use std::env;
use std::fs;
use std::path::Path;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        print_usage(&args[0]);
        return;
    }

    let command = &args[1];

    match command.as_str() {
        "compile" | "build" => {
            if args.len() < 3 {
                eprintln!("Usage: {} {} <file.fv>", args[0], command);
                return;
            }
            compile_file(&args[2]);
        }
        "run" => {
            if args.len() < 3 {
                eprintln!("Usage: {} run <file.fv> [args...]", args[0]);
                return;
            }
            // 스크립트 인자를 환경변수로 전달 (args() 함수가 읽을 수 있도록)
            let script_args: Vec<String> = std::iter::once(args[2].clone())
                .chain(args[3..].iter().cloned())
                .collect();
            run_file(&args[2], &script_args);
        }
        "help" | "--help" | "-h" => {
            print_help();
        }
        "version" | "--version" | "-v" => {
            println!("FV-Lang 0.1.0");
        }
        _ => {
            eprintln!("Unknown command: {}", command);
            print_usage(&args[0]);
        }
    }
}

/// FreeLang 스크립트 실행
fn run_file(filename: &str, script_args: &[String]) {
    let path = Path::new(filename);
    if !path.exists() {
        eprintln!("오류: 파일 없음: {}", filename);
        return;
    }
    let source = match fs::read_to_string(path) {
        Ok(s) => s,
        Err(e) => { eprintln!("파일 읽기 오류: {}", e); return; }
    };

    // 인자를 임시 환경변수로 주입 (스크립트에서 args() 호출 시 사용)
    let args_json: String = script_args.iter()
        .map(|a| format!("\"{}\"", a))
        .collect::<Vec<_>>()
        .join(",");
    env::set_var("FV_ARGS", format!("[{}]", args_json));

    let mut compiler = Compiler::new();
    match compiler.compile_and_run(&source) {
        Ok(val) => {
            match val {
                fv_lang::Value::None => {}
                other => println!("{:?}", other),
            }
        }
        Err(e) => eprintln!("실행 오류: {}", e),
    }
}

