                return;
            }
            compile_file(&args[2]);
        }
        "run" => {
            if args.len() < 3 {
                eprintln!("Usage: {} run <file.fv> [args...]", args[0]);
                return;
            }
            // 스크립트 인자를 환경변수로 전달 (args() 함수가 읽을 수 있도록)
            let script_args: Vec<String> = std::iter::once(args[2].clone())
                .chain(args[3..].iter().cloned())
                .collect();
            run_file(&args[2], &script_args);
